/*
Custom Blockly blocks for Test in a Box.

The generic set/read blocks remain available for every instrument position.
PSU-specific blocks provide a clearer engineering workflow and hide channel
details when a configured PSU has only one output.

Dropdown values are populated by app.js from GET /api/devices.
*/

// Generic instrument positions.
window.HW_OUTPUT_POSITIONS = [["(no output instruments)", "none|none"]];
window.HW_INPUT_POSITIONS = [["(no input instruments)", "none|none"]];

// PSU-specific position lists. Labels are generated by app.js. For a
// single-output PSU, labels omit channel information. Multi-output PSUs include
// the channel in the label.
window.HW_PSU_VOLTAGE_OUTPUTS = [["(no PSU voltage outputs)", "none|none"]];
window.HW_PSU_CURRENT_OUTPUTS = [["(no PSU current outputs)", "none|none"]];
window.HW_PSU_OUTPUT_SWITCHES = [["(no PSU outputs)", "none|none"]];
window.HW_PSU_VOLTAGE_INPUTS = [["(no PSU voltage measurements)", "none|none"]];
window.HW_PSU_CURRENT_INPUTS = [["(no PSU current measurements)", "none|none"]];

// Relay-specific lists populated by app.js.
window.HW_RELAY_POSITIONS = [["(no relay channels)", "none|none"]];
window.HW_RELAY_BANKS = [[
  "(no relay banks)",
  "{\"deviceId\":\"none\",\"positions\":[]}"
]];


Blockly.Blocks['hw_set'] = {
  init: function () {
    this.appendDummyInput()
      .appendField("set")
      .appendField(
        new Blockly.FieldDropdown(() => window.HW_OUTPUT_POSITIONS),
        "POSITION"
      )
      .appendField("to");
    this.appendValueInput("VALUE").setCheck(null);
    this.setPreviousStatement(true, null);
    this.setNextStatement(true, null);
    this.setColour(210);
    this.setTooltip(
      "Write a value to a generic output position."
    );
  }
};


Blockly.Blocks['hw_get'] = {
  init: function () {
    this.appendDummyInput()
      .appendField("read")
      .appendField(
        new Blockly.FieldDropdown(() => window.HW_INPUT_POSITIONS),
        "POSITION"
      );
    this.setOutput(true, null);
    this.setColour(210);
    this.setTooltip(
      "Read a value from a generic input position."
    );
  }
};


// ---------------------------------------------------------------------------
// PSU engineering blocks
// ---------------------------------------------------------------------------

Blockly.Blocks['hw_psu_set_voltage'] = {
  init: function () {
    this.appendDummyInput()
      .appendField("set PSU voltage")
      .appendField(
        new Blockly.FieldDropdown(() => window.HW_PSU_VOLTAGE_OUTPUTS),
        "POSITION"
      );
    this.appendValueInput("VALUE")
      .setCheck("Number")
      .appendField("to");
    this.appendDummyInput()
      .appendField("V");
    this.setInputsInline(true);
    this.setPreviousStatement(true, null);
    this.setNextStatement(true, null);
    this.setColour(210);
    this.setTooltip(
      "Set a PSU voltage. Channel information is hidden for single-output PSUs."
    );
  }
};


Blockly.Blocks['hw_psu_set_current'] = {
  init: function () {
    this.appendDummyInput()
      .appendField("set PSU current limit")
      .appendField(
        new Blockly.FieldDropdown(() => window.HW_PSU_CURRENT_OUTPUTS),
        "POSITION"
      );
    this.appendValueInput("VALUE")
      .setCheck("Number")
      .appendField("to");
    this.appendDummyInput()
      .appendField("A");
    this.setInputsInline(true);
    this.setPreviousStatement(true, null);
    this.setNextStatement(true, null);
    this.setColour(210);
    this.setTooltip(
      "Set a PSU current limit. Channel information is hidden for single-output PSUs."
    );
  }
};


Blockly.Blocks['hw_psu_output'] = {
  init: function () {
    this.appendDummyInput()
      .appendField("PSU output")
      .appendField(
        new Blockly.FieldDropdown(() => window.HW_PSU_OUTPUT_SWITCHES),
        "POSITION"
      )
      .appendField(
        new Blockly.FieldDropdown([
          ["ON", "ON"],
          ["OFF", "OFF"],
        ]),
        "STATE"
      );
    this.setPreviousStatement(true, null);
    this.setNextStatement(true, null);
    this.setColour(210);
    this.setTooltip(
      "Turn a PSU output ON or OFF without using numeric 1/0 values."
    );
  }
};


Blockly.Blocks['hw_psu_read_voltage'] = {
  init: function () {
    this.appendDummyInput()
      .appendField("read PSU voltage")
      .appendField(
        new Blockly.FieldDropdown(() => window.HW_PSU_VOLTAGE_INPUTS),
        "POSITION"
      );
    this.setOutput(true, "Number");
    this.setColour(210);
    this.setTooltip(
      "Read measured PSU voltage. Channel information is hidden for single-output PSUs."
    );
  }
};


Blockly.Blocks['hw_psu_read_current'] = {
  init: function () {
    this.appendDummyInput()
      .appendField("read PSU current")
      .appendField(
        new Blockly.FieldDropdown(() => window.HW_PSU_CURRENT_INPUTS),
        "POSITION"
      );
    this.setOutput(true, "Number");
    this.setColour(210);
    this.setTooltip(
      "Read measured PSU current. Channel information is hidden for single-output PSUs."
    );
  }
};


Blockly.Blocks['hw_psu_ramp_voltage'] = {
  init: function () {
    this.appendDummyInput()
      .appendField("ramp PSU voltage")
      .appendField(
        new Blockly.FieldDropdown(() => window.HW_PSU_VOLTAGE_OUTPUTS),
        "POSITION"
      );

    this.appendDummyInput()
      .appendField("from")
      .appendField(new Blockly.FieldNumber(0), "START")
      .appendField("V to")
      .appendField(new Blockly.FieldNumber(12), "END")
      .appendField("V");

    this.appendDummyInput()
      .appendField("step")
      .appendField(new Blockly.FieldNumber(0.1, 0.000001), "STEP")
      .appendField("V");

    this.appendDummyInput()
      .appendField("dwell")
      .appendField(new Blockly.FieldNumber(100, 0), "DWELL")
      .appendField(
        new Blockly.FieldDropdown([
          ["ms", "MS"],
          ["s", "S"],
        ]),
        "DWELL_UNIT"
      );

    this.setPreviousStatement(true, null);
    this.setNextStatement(true, null);
    this.setColour(210);
    this.setTooltip(
      "Ramp a PSU voltage up or down. Enter a positive step magnitude; " +
      "the direction is determined automatically from the start and end values."
    );
  }
};


// ---------------------------------------------------------------------------
// Relay engineering blocks
// ---------------------------------------------------------------------------

Blockly.Blocks['hw_relay_set'] = {
  init: function () {
    this.appendDummyInput()
      .appendField("set relay")
      .appendField(
        new Blockly.FieldDropdown(() => window.HW_RELAY_POSITIONS),
        "POSITION"
      )
      .appendField(
        new Blockly.FieldDropdown([
          ["ON", "ON"],
          ["OFF", "OFF"],
        ]),
        "STATE"
      );
    this.setPreviousStatement(true, null);
    this.setNextStatement(true, null);
    this.setColour(120);
    this.setTooltip(
      "Turn one relay channel ON or OFF."
    );
  }
};


Blockly.Blocks['hw_relay_read'] = {
  init: function () {
    this.appendDummyInput()
      .appendField("read relay state")
      .appendField(
        new Blockly.FieldDropdown(() => window.HW_RELAY_POSITIONS),
        "POSITION"
      );
    this.setOutput(true, "Boolean");
    this.setColour(120);
    this.setTooltip(
      "Read a relay channel state. Returns true for ON and false for OFF."
    );
  }
};


Blockly.Blocks['hw_relay_all'] = {
  init: function () {
    this.appendDummyInput()
      .appendField("set relay bank")
      .appendField(
        new Blockly.FieldDropdown(() => window.HW_RELAY_BANKS),
        "BANK"
      )
      .appendField(
        new Blockly.FieldDropdown([
          ["ALL ON", "ON"],
          ["ALL OFF", "OFF"],
        ]),
        "STATE"
      );
    this.setPreviousStatement(true, null);
    this.setNextStatement(true, null);
    this.setColour(120);
    this.setTooltip(
      "Turn every relay in the selected relay bank ON or OFF."
    );
  }
};


// ---------------------------------------------------------------------------
// Timing, results and checks
// ---------------------------------------------------------------------------

Blockly.Blocks['hw_wait'] = {
  init: function () {
    this.appendValueInput("SECONDS")
      .setCheck("Number")
      .appendField("wait");
    this.appendDummyInput()
      .appendField("seconds");
    this.setPreviousStatement(true, null);
    this.setNextStatement(true, null);
    this.setColour(65);
  }
};


Blockly.Blocks['hw_log'] = {
  init: function () {
    this.appendDummyInput()
      .appendField("log")
      .appendField(
        new Blockly.FieldTextInput("Measured value"),
        "MESSAGE"
      );
    this.appendValueInput("VALUE")
      .setCheck(null)
      .appendField("value");
    this.setPreviousStatement(true, null);
    this.setNextStatement(true, null);
    this.setColour(65);
    this.setTooltip(
      "Record a labelled engineering value. The value can be a measurement, " +
      "variable, number, calculation, or text."
    );
  }
};


Blockly.Blocks['hw_assert'] = {
  init: function () {
    this.appendValueInput("CONDITION")
      .setCheck(null)
      .appendField("assert");
    this.appendDummyInput()
      .appendField("message")
      .appendField(
        new Blockly.FieldTextInput("check passed"),
        "MESSAGE"
      );
    this.setPreviousStatement(true, null);
    this.setNextStatement(true, null);
    this.setColour(0);
    this.setTooltip(
      "Record a pass/fail check. The procedure stops on failure."
    );
  }
};


// Populated by app.js after fetching /api/duts.
window.HW_DUTS = [["(no DUTs configured)", "none"]];


Blockly.Blocks['hw_prompt'] = {
  init: function () {
    this.appendDummyInput()
      .appendField("ask operator for")
      .appendField(
        new Blockly.FieldTextInput("Serial Number"),
        "LABEL"
      )
      .appendField("and record for DUT")
      .appendField(
        new Blockly.FieldDropdown(() => window.HW_DUTS),
        "DUT"
      );
    this.setPreviousStatement(true, null);
    this.setNextStatement(true, null);
    this.setColour(290);
    this.setTooltip(
      "Pause the run, ask the operator for a value, and record it against a DUT."
    );
  }
};


Blockly.Blocks['hw_within_tolerance'] = {
  init: function () {
    this.appendValueInput("MEASURED")
      .setCheck(null)
      .appendField("is");
    this.appendValueInput("TARGET")
      .setCheck(null)
      .appendField("within");
    this.appendValueInput("TOLERANCE")
      .setCheck(null)
      .appendField("of");
    this.setInputsInline(true);
    this.setOutput(true, "Boolean");
    this.setColour(0);
    this.setTooltip(
      "True when the measured value is within the stated tolerance of the target."
    );
  }
};
